'use strict';
/**
 * View-pack capture for fix/web-quotation-truth — INTERCEPTED renders.
 *
 * Runs against `next dev` of this worktree (default http://127.0.0.1:3217).
 * No backend runs: every /api/ request the page makes is answered here from
 * fixtures/ (quotations-response.json is the NEW response shape; its issuer /
 * copy / signatory were generated by the real backend builders —
 * fixtures/server-blocks-ginger.json). Unanswered /api/ paths are logged.
 *
 * Shots (light + dark):
 *   quotation-step-*.png   /health/applications/new/step/10 (the real step; a
 *                          fake unsigned health JWT passes the middleware's
 *                          role decode, and sessionStorage gacp_edit_mode lets
 *                          the step render without walking steps 1-6)
 *
 * Usage: node capture-view-pack.js  (puppeteer from apps/backend/node_modules)
 */
const fs = require('fs');
const path = require('path');
const puppeteer = require(path.join(__dirname, '../../apps/backend/node_modules/puppeteer'));

const BASE = process.env.VIEWPACK_BASE || 'http://127.0.0.1:3217';
const OUT = __dirname;
const quotations = JSON.parse(fs.readFileSync(path.join(OUT, 'fixtures/quotations-response.json'), 'utf8'));
const APP_ID = 'app-viewpack';

const draft = {
    success: true,
    data: {
        id: APP_ID, draftId: APP_ID, status: 'PENDING_DOC_FEE',
        formData: {
            plantId: 'ginger', requestType: 'NEW', certScope: 'PLANTING', applicantType: 'JURISTIC',
            cultivationMethods: ['OUTDOOR'],
        },
    },
};

function b64url(o) { return Buffer.from(JSON.stringify(o)).toString('base64url'); }
const FAKE_JWT = `${b64url({ alg: 'none', typ: 'JWT' })}.${b64url({ role: 'health', canonicalRole: 'health', sub: 'viewpack' })}.x`;

function answer(url) {
    const p = new URL(url).pathname;
    if (/\/applications\/[^/]+\/quotations$/.test(p)) { return quotations; }
    if (/\/applications\/draft$/.test(p)) { return draft; }
    if (/\/applications\/config$/.test(p)) { return { success: true, data: { steps: [1, 2, 3, 4, 5, 6, 10, 12] } }; }
    if (new RegExp(`/applications/${APP_ID}$`).test(p)) { return { success: true, data: { id: APP_ID, status: 'PENDING_DOC_FEE' } }; }
    return null;
}

async function shoot(browser, { url, dark, file, selector }) {
    const page = await browser.newPage();
    await page.setViewport({ width: 1366, height: 1000, deviceScaleFactor: 1 });
    await page.setCookie({ name: 'auth_token', value: FAKE_JWT, url: BASE });
    await page.evaluateOnNewDocument((isDark, appId) => {
        localStorage.setItem('theme', isDark ? 'dark' : 'light');
        localStorage.setItem('theme:explicit', '1');
        sessionStorage.setItem('gacp_edit_mode', JSON.stringify({ isEditMode: true, applicationId: appId }));
    }, dark, APP_ID);
    await page.setRequestInterception(true);
    const unanswered = new Set();
    page.on('request', (req) => {
        const u = req.url();
        if (u.includes('/_next/') || !u.includes('/api/')) { return req.continue(); }
        const body = answer(u);
        if (body) {
            return req.respond({ status: 200, contentType: 'application/json', body: JSON.stringify(body) });
        }
        unanswered.add(new URL(u).pathname);
        return req.respond({ status: 200, contentType: 'application/json', body: JSON.stringify({ success: true, data: null }) });
    });
    await page.goto(`${BASE}${url}`, { waitUntil: 'networkidle0', timeout: 180000 });
    await page.waitForSelector(selector, { timeout: 120000 });
    await new Promise((r) => setTimeout(r, 1500));
    await page.screenshot({ path: path.join(OUT, file), fullPage: true });
    const text = await page.evaluate(() => document.body.innerText);
    await page.close();
    return { file, unanswered: [...unanswered], text };
}

(async () => {
    const browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox'] });
    const results = [];
    try {
        for (const dark of [false, true]) {
            const mode = dark ? 'dark' : 'light';
            results.push(await shoot(browser, {
                url: '/health/applications/new/step/10', dark, file: `quotation-step-${mode}.png`, selector: '#dtam-document',
            }));
        }
    } finally {
        await browser.close();
    }
    const RETIRED = ['ระบบรับรองมาตรฐาน GACP สมุนไพร', '0-2591-7007', '88/23', 'ติวานนท์', 'contact@gacpth.com', 'กัญชา', 'นายปรีชา', 'นายรชต', 'หลักฐานการชำระเงิน'];
    const lines = [];
    for (const r of results) {
        const hits = RETIRED.filter((w) => r.text.includes(w));
        const emoji = /\p{Extended_Pictographic}/u.test(r.text);
        const has = ['บริษัท พรีดิกทีฟ เอไอ โซลูชัน จำกัด', '0105568045932', 'finance@gacpth.com', 'คำขอจะเข้าสู่ขั้นตอนตรวจเอกสารหลังระบบยืนยันการชำระค่าบริการงวดที่ 1 แล้ว'].map((w) => `${w}:${r.text.includes(w)}`);
        lines.push(`${r.file} retired-hits=[${hits.join(',')}] emoji=${emoji} ${has.join(' ')} ขิง:${r.text.includes('ขิง')} unanswered-api=[${r.unanswered.join(',')}]`);
    }
    fs.writeFileSync(path.join(OUT, 'capture-check.txt'), `${lines.join('\n')}\n`);
    console.log(lines.join('\n'));
})().catch((e) => { console.error(e); process.exit(1); });
